import { Checkbox, Fieldset, NativeSelect, NumberInput, Stack } from '@mantine/core';
import { getMoneyInputProps } from '../money';
import type { InvoiceFormType } from '../types';
import classes from './Adjustments.module.css';

export function Adjustments({ form }: { form: InvoiceFormType }) {
  const currency = form.useWatchValue('currency');
  const discountEnabled = form.useWatchValue('discountEnabled');
  const discountType = form.useWatchValue('discountType');
  const moneyProps = getMoneyInputProps(currency);

  const discountProps =
    discountType === 'percentage'
      ? { suffix: '%', decimalScale: 2, allowNegative: false, hideControls: true }
      : moneyProps;

  return (
    <Fieldset legend="Adjustments" classNames={{ legend: classes.legend }}>
      <Stack>
        <Stack gap="xs">
          <Checkbox
            label="Apply a discount before tax"
            {...form.getInputProps('discountEnabled', { type: 'checkbox' })}
          />
          {discountEnabled && (
            <NumberInput
              label="Discount"
              placeholder={discountType === 'percentage' ? 'Percentage' : 'Amount'}
              withAsterisk
              rightSection={
                <NativeSelect
                  aria-label="Discount type"
                  data={[
                    { value: 'percentage', label: '%' },
                    { value: 'fixed', label: currency },
                  ]}
                  variant="unstyled"
                  rightSectionWidth={28}
                  {...form.getInputProps('discountType', { withError: false })}
                />
              }
              rightSectionWidth={84}
              {...discountProps}
              {...form.getInputProps('discountValue')}
            />
          )}
        </Stack>

        <NumberInput
          label="Shipping"
          placeholder="Shipping"
          description="Taxed at the first item's rate"
          {...moneyProps}
          {...form.getInputProps('shipping')}
        />
      </Stack>
    </Fieldset>
  );
}

import { Alert, Anchor, List } from '@mantine/core';
import type { InvoiceFormType } from './types';

const FIELD_LABELS: Record<string, string> = {
  clientId: 'Client',
  invoiceNumber: 'Invoice number',
  issueDate: 'Issue date',
  dueDate: 'Due date',
  items: 'Line items',
  discountValue: 'Discount',
  shipping: 'Shipping',
  customTermDays: 'Days until due',
  paymentMethods: 'Accepted payment methods',
  notes: 'Notes to the client',
};

const ITEM_FIELD_LABELS: Record<string, string> = {
  description: 'description',
  quantity: 'quantity',
  unitPrice: 'unit price',
  customTaxRate: 'custom tax rate',
};

function getLabel(path: string) {
  const item = /^items\.(\d+)\.(\w+)$/.exec(path);
  if (item) {
    return `Item ${Number(item[1]) + 1} ${ITEM_FIELD_LABELS[item[2]] ?? item[2]}`;
  }
  return FIELD_LABELS[path] ?? path;
}

interface ErrorSummaryProps {
  form: InvoiceFormType;
  onSelect: (path: string) => void;
}

export function ErrorSummary({ form, onSelect }: ErrorSummaryProps) {
  const entries = Object.entries(form.errors);

  if (entries.length === 0) {
    return null;
  }

  return (
    <Alert color="red" title="There is a problem">
      <List size="sm">
        {entries.map(([path, error]) => (
          <List.Item key={path}>
            <Anchor component="button" type="button" size="sm" onClick={() => onSelect(path)}>
              {getLabel(path)}
            </Anchor>
            : {error}
          </List.Item>
        ))}
      </List>
    </Alert>
  );
}

