import dayjs from 'dayjs';
import { useRef } from 'react';
import { getTermDays } from './payload';
import type { InvoiceFormType } from './types';
import { getCurrency } from './validation';

const DATE_FORMAT = 'YYYY-MM-DD';

const addDays = (date: string, days: number) => dayjs(date).add(days, 'day').format(DATE_FORMAT);

export function useDueDateSync(form: InvoiceFormType) {
  // The due date follows the issue date and the payment terms until the user types a due date
  const generatedDueDate = useRef(form.getValues().dueDate);
  const dueDateEdited = useRef(false);
  const lastIssueDate = useRef(form.getValues().issueDate);

  const setDueDate = (value: string) => {
    generatedDueDate.current = value;
    dueDateEdited.current = false;
    form.setFieldValue('dueDate', value);
  };

  const applyTerms = () => {
    const values = form.getValues();
    const days = getTermDays(values);
    if (values.issueDate && days !== null && Number.isInteger(days) && days >= 0 && days <= 180) {
      setDueDate(addDays(values.issueDate, days));
    }
  };

  form.watch('dueDate', ({ value }) => {
    if (value !== generatedDueDate.current) {
      dueDateEdited.current = true;
    }
  });

  form.watch('issueDate', ({ value }) => {
    // The masked input reports null while a part is incomplete: shift from the last complete date
    if (!value) {
      return;
    }
    const previous = lastIssueDate.current;
    lastIssueDate.current = value;
    const { dueDate } = form.getValues();

    if (!dueDateEdited.current && previous && dueDate) {
      setDueDate(addDays(dueDate, dayjs(value).diff(previous, 'day')));
    } else if (form.errors.dueDate) {
      form.validateField('dueDate');
    }
  });

  form.watch('paymentTerms', applyTerms);
  form.watch('customTermDays', applyTerms);
}

export function useWholeAmountsForCurrency(form: InvoiceFormType) {
  // Money inputs drop decimals for JPY: round the stored amounts so totals match what is displayed
  form.watch('currency', ({ value }) => {
    const factor = 10 ** getCurrency(value).decimals;
    const roundField = (path: string, amount: number | string) => {
      const rounded = amount === '' ? amount : Math.round(Number(amount) * factor) / factor;
      if (rounded !== amount) {
        form.setFieldValue(path, rounded);
      }
    };
    const values = form.getValues();

    values.items.forEach((item, index) => roundField(`items.${index}.unitPrice`, item.unitPrice));
    roundField('shipping', values.shipping);
    if (values.discountType === 'fixed') {
      roundField('discountValue', values.discountValue);
    }
  });
}

export function useClearHiddenErrors(form: InvoiceFormType) {
  form.watch('discountEnabled', ({ value }) => {
    if (!value) {
      form.clearFieldError('discountValue');
    }
  });

  form.watch('paymentTerms', ({ value }) => {
    if (value !== 'custom') {
      form.clearFieldError('customTermDays');
    }
  });
}

import { computeTotals, formatMoney } from './money';
import type { LineItemValues } from './types';

const item = (overrides: Partial<LineItemValues>): LineItemValues => ({
  id: 'item',
  description: 'Work',
  quantity: 1,
  unit: 'hours',
  unitPrice: 0,
  taxRate: '19',
  customTaxRate: '',
  ...overrides,
});

const base = {
  currency: 'USD' as const,
  discountEnabled: false,
  discountType: 'percentage' as const,
  discountValue: '' as number | string,
  shipping: '' as number | string,
};

describe('computeTotals', () => {
  it('sums line amounts in minor units', () => {
    const totals = computeTotals({
      ...base,
      items: [item({ quantity: 1.5, unitPrice: 80 }), item({ quantity: 3, unitPrice: 0.1 })],
    });

    expect(totals.lineAmounts).toEqual([12000, 30]);
    expect(totals.subtotal).toBe(12030);
  });

  it('returns one tax line per distinct rate, highest rate first', () => {
    const totals = computeTotals({
      ...base,
      items: [
        item({ unitPrice: 100, taxRate: '7' }),
        item({ unitPrice: 200, taxRate: '19' }),
        item({ unitPrice: 50, taxRate: 'custom', customTaxRate: 19 }),
      ],
    });

    expect(totals.taxes).toEqual([
      { rate: 19, amount: 4750 },
      { rate: 7, amount: 700 },
    ]);
  });

  it('applies a percentage discount before tax', () => {
    const totals = computeTotals({
      ...base,
      discountEnabled: true,
      discountValue: 10,
      items: [item({ unitPrice: 1000 })],
    });

    expect(totals).toMatchObject({
      discount: 10000,
      taxes: [{ rate: 19, amount: 17100 }],
      total: 107100,
    });
  });

  it('taxes shipping at the first item rate', () => {
    const totals = computeTotals({
      ...base,
      shipping: 10,
      items: [item({ unitPrice: 100, taxRate: '7' }), item({ unitPrice: 100, taxRate: '19' })],
    });

    expect(totals.taxes).toEqual([
      { rate: 19, amount: 1900 },
      { rate: 7, amount: 770 },
    ]);
    expect(totals.total).toBe(20000 + 1000 + 1900 + 770);
  });

  it('does not tax a negative base when a fixed discount exceeds the subtotal', () => {
    const totals = computeTotals({
      ...base,
      discountEnabled: true,
      discountType: 'fixed',
      discountValue: 150,
      items: [item({ unitPrice: 100 })],
    });

    expect(totals).toMatchObject({ taxes: [{ rate: 19, amount: 0 }], total: -5000 });
  });

  it('uses whole yen for JPY', () => {
    const totals = computeTotals({
      ...base,
      currency: 'JPY',
      items: [item({ quantity: 3, unitPrice: 1500 })],
    });

    expect(totals.subtotal).toBe(4500);
    expect(formatMoney(totals.total, 'JPY')).toBe('¥5,355');
  });
});

import type { Currency, InvoiceTotals, InvoiceValues, LineItemValues, TaxLine } from './types';
import { getCurrency } from './validation';

type TotalsInput = Pick<
  InvoiceValues,
  'items' | 'currency' | 'discountEnabled' | 'discountType' | 'discountValue' | 'shipping'
>;

const toNumber = (value: number | string) => {
  const number = Number(value);
  return value === '' || Number.isNaN(number) ? 0 : number;
};

export const toMinor = (amount: number | string, currency: Currency) =>
  Math.round(toNumber(amount) * 10 ** getCurrency(currency).decimals);

export function formatMoney(minor: number, currency: Currency) {
  const { decimals } = getCurrency(currency);
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency,
    minimumFractionDigits: decimals,
    maximumFractionDigits: decimals,
  }).format(minor / 10 ** decimals);
}

export function getMoneyInputProps(currency: Currency) {
  const { symbol, decimals } = getCurrency(currency);
  return {
    prefix: symbol,
    decimalScale: decimals,
    allowDecimal: decimals > 0,
    thousandSeparator: ',',
    allowNegative: false,
    hideControls: true,
  };
}

export const getItemTaxRate = (item: LineItemValues) =>
  item.taxRate === 'custom' ? toNumber(item.customTaxRate) : Number(item.taxRate);

export const getLineAmount = (item: LineItemValues, currency: Currency) =>
  Math.round(
    toNumber(item.quantity) * toNumber(item.unitPrice) * 10 ** getCurrency(currency).decimals
  );

export function computeTotals(values: TotalsInput): InvoiceTotals {
  const { items, currency } = values;
  const lineAmounts = items.map((item) => getLineAmount(item, currency));
  const subtotal = lineAmounts.reduce((sum, amount) => sum + amount, 0);

  let discount = 0;
  if (values.discountEnabled) {
    discount =
      values.discountType === 'percentage'
        ? Math.round((subtotal * toNumber(values.discountValue)) / 100)
        : toMinor(values.discountValue, currency);
  }

  // The discount reduces every rate's base in proportion; a discount above the subtotal leaves nothing to tax
  const discountedShare = subtotal > 0 ? Math.max(0, subtotal - discount) / subtotal : 0;
  const shipping = toMinor(values.shipping, currency);

  const bases = new Map<number, number>();
  items.forEach((item, index) => {
    const rate = getItemTaxRate(item);
    bases.set(rate, (bases.get(rate) ?? 0) + lineAmounts[index] * discountedShare);
  });
  if (items.length > 0 && shipping > 0) {
    const shippingRate = getItemTaxRate(items[0]);
    bases.set(shippingRate, (bases.get(shippingRate) ?? 0) + shipping);
  }

  const taxes: TaxLine[] = [...bases.entries()]
    .sort(([a], [b]) => b - a)
    .map(([rate, base]) => ({ rate, amount: Math.round((base * rate) / 100) }));

  const taxTotal = taxes.reduce((sum, tax) => sum + tax.amount, 0);

  return {
    lineAmounts,
    subtotal,
    discount,
    taxes,
    shipping,
    total: subtotal - discount + taxTotal + shipping,
  };
}

import { computeTotals, getItemTaxRate, toMinor } from './money';
import type { Client, InvoicePayload, InvoiceValues } from './types';
import { PAYMENT_TERMS } from './validation';

const toNumber = (value: number | string) => (value === '' ? 0 : Number(value));

export function getTermDays(values: Pick<InvoiceValues, 'paymentTerms' | 'customTermDays'>) {
  if (values.paymentTerms === 'custom') {
    return values.customTermDays === '' ? null : Number(values.customTermDays);
  }
  return PAYMENT_TERMS.find((term) => term.value === values.paymentTerms)?.days ?? null;
}

function buildDiscount(values: InvoiceValues, amount: number): InvoicePayload['discount'] {
  if (!values.discountEnabled) {
    return { type: 'none', amount: 0 };
  }
  return values.discountType === 'percentage'
    ? { type: 'percentage', percentage: toNumber(values.discountValue), amount }
    : { type: 'fixed', amount };
}

export function buildPayload(values: InvoiceValues, clients: Client[]): InvoicePayload {
  const totals = computeTotals(values);

  return {
    status: 'issued',
    invoiceNumber: values.invoiceNumber.trim(),
    client: clients.find((client) => client.id === values.clientId) ?? null,
    issueDate: values.issueDate,
    dueDate: values.dueDate,
    currency: values.currency,
    purchaseOrderNumber: values.purchaseOrderNumber.trim() || null,
    items: values.items.map((item, index) => ({
      description: item.description.trim(),
      quantity: toNumber(item.quantity),
      unit: item.unit,
      unitPrice: toMinor(item.unitPrice, values.currency),
      taxRate: getItemTaxRate(item),
      amount: totals.lineAmounts[index],
    })),
    discount: buildDiscount(values, totals.discount),
    shipping: totals.shipping,
    totals: {
      subtotal: totals.subtotal,
      discount: totals.discount,
      taxes: totals.taxes,
      shipping: totals.shipping,
      total: totals.total,
    },
    payment: {
      terms: values.paymentTerms,
      termDays: getTermDays(values),
      methods: values.paymentMethods,
    },
    notes: values.notes.trim(),
    internalMemo: values.internalMemo.trim(),
  };
}

import type { UseFormReturnType } from '@mantine/form';

export type Currency = 'USD' | 'EUR' | 'GBP' | 'JPY';
export type Unit = 'hours' | 'days' | 'pieces' | 'flat';
export type TaxRateOption = '0' | '7' | '19' | 'custom';
export type DiscountType = 'percentage' | 'fixed';
export type PaymentTerms = 'receipt' | 'net15' | 'net30' | 'net60' | 'custom';
export type PaymentMethod = 'bank_transfer' | 'card' | 'paypal';

export interface Client {
  id: string;
  name: string;
  address: string[];
}

export interface LineItemValues {
  id: string;
  description: string;
  quantity: number | string;
  unit: Unit;
  unitPrice: number | string;
  taxRate: TaxRateOption;
  customTaxRate: number | string;
}

export interface InvoiceValues {
  clientId: string | null;
  invoiceNumber: string;
  issueDate: string | null;
  dueDate: string | null;
  currency: Currency;
  purchaseOrderNumber: string;
  items: LineItemValues[];
  discountEnabled: boolean;
  discountType: DiscountType;
  discountValue: number | string;
  shipping: number | string;
  paymentTerms: PaymentTerms;
  customTermDays: number | string;
  paymentMethods: PaymentMethod[];
  notes: string;
  internalMemo: string;
}

export interface TaxLine {
  rate: number;
  amount: number;
}

/** All amounts in minor units (cents, or whole yen) */
export interface InvoiceTotals {
  lineAmounts: number[];
  subtotal: number;
  discount: number;
  taxes: TaxLine[];
  shipping: number;
  total: number;
}

export interface InvoicePayload {
  status: 'issued' | 'draft';
  invoiceNumber: string;
  client: Client | null;
  issueDate: string | null;
  dueDate: string | null;
  currency: Currency;
  purchaseOrderNumber: string | null;
  items: {
    description: string;
    quantity: number;
    unit: Unit;
    unitPrice: number;
    taxRate: number;
    amount: number;
  }[];
  discount:
    | { type: 'none'; amount: 0 }
    | { type: 'percentage'; percentage: number; amount: number }
    | { type: 'fixed'; amount: number };
  shipping: number;
  totals: {
    subtotal: number;
    discount: number;
    taxes: TaxLine[];
    shipping: number;
    total: number;
  };
  payment: {
    terms: PaymentTerms;
    termDays: number | null;
    methods: PaymentMethod[];
  };
  notes: string;
  internalMemo: string;
}

export type InvoiceFormType = UseFormReturnType<InvoiceValues, InvoicePayload>;

import dayjs from 'dayjs';
import { formRootRule, isNotEmpty, when, type FormRulesRecord } from '@mantine/form';
import type {
  Currency,
  InvoiceValues,
  LineItemValues,
  PaymentMethod,
  PaymentTerms,
  TaxRateOption,
  Unit,
} from './types';

export const MIN_ITEMS = 1;
export const MAX_ITEMS = 50;
export const NOTES_MAX_LENGTH = 500;

export const CURRENCIES: { value: Currency; label: string; symbol: string; decimals: number }[] = [
  { value: 'USD', label: 'USD – US dollar', symbol: '$', decimals: 2 },
  { value: 'EUR', label: 'EUR – Euro', symbol: '€', decimals: 2 },
  { value: 'GBP', label: 'GBP – British pound', symbol: '£', decimals: 2 },
  { value: 'JPY', label: 'JPY – Japanese yen', symbol: '¥', decimals: 0 },
];

export const UNITS: { value: Unit; label: string }[] = [
  { value: 'hours', label: 'hours' },
  { value: 'days', label: 'days' },
  { value: 'pieces', label: 'pieces' },
  { value: 'flat', label: 'flat' },
];

export const TAX_RATES: { value: TaxRateOption; label: string }[] = [
  { value: '0', label: '0%' },
  { value: '7', label: '7%' },
  { value: '19', label: '19%' },
  { value: 'custom', label: 'Custom' },
];

export const PAYMENT_TERMS: { value: PaymentTerms; label: string; days: number | null }[] = [
  { value: 'receipt', label: 'Due on receipt', days: 0 },
  { value: 'net15', label: 'Net 15', days: 15 },
  { value: 'net30', label: 'Net 30', days: 30 },
  { value: 'net60', label: 'Net 60', days: 60 },
  { value: 'custom', label: 'Custom', days: null },
];

export const PAYMENT_METHODS: { value: PaymentMethod; label: string }[] = [
  { value: 'bank_transfer', label: 'Bank transfer' },
  { value: 'card', label: 'Card' },
  { value: 'paypal', label: 'PayPal' },
];

export const getCurrency = (currency: Currency) =>
  CURRENCIES.find((item) => item.value === currency) ?? CURRENCIES[0];

const isBlank = (value: number | string) => value === '' || value === null || value === undefined;

const decimalsOf = (value: number) => (String(value).split('.')[1] ?? '').length;

const quantityRule = (value: number | string) => {
  if (isBlank(value)) {
    return 'Enter a quantity';
  }
  if (Number(value) <= 0) {
    return 'Quantity must be greater than 0';
  }
  return decimalsOf(Number(value)) > 3 ? 'Use up to 3 decimals' : null;
};

const unitPriceRule = (value: number | string) => {
  if (isBlank(value)) {
    return 'Enter a unit price';
  }
  return Number(value) < 0 ? 'Unit price cannot be negative' : null;
};

const customTaxRateRule = (value: number | string) => {
  if (isBlank(value)) {
    return 'Enter a tax rate';
  }
  const rate = Number(value);
  if (rate < 0 || rate > 100) {
    return 'Tax rate must be between 0 and 100';
  }
  return decimalsOf(rate) > 1 ? 'Use one decimal at most' : null;
};

const discountRule = (value: number | string, values: InvoiceValues) => {
  if (isBlank(value)) {
    return 'Enter a discount';
  }
  const discount = Number(value);
  if (values.discountType === 'percentage' && (discount < 0 || discount > 100)) {
    return 'Percentage must be between 0 and 100';
  }
  return discount < 0 ? 'Discount cannot be negative' : null;
};

const customTermDaysRule = (value: number | string) => {
  const days = Number(value);
  return isBlank(value) || !Number.isInteger(days) || days < 1 || days > 180
    ? 'Enter between 1 and 180 days'
    : null;
};

const dueDateRule = (value: string | null, values: InvoiceValues) => {
  if (!value) {
    return 'Enter a due date';
  }
  return values.issueDate && dayjs(value).isBefore(values.issueDate, 'day')
    ? 'Due date cannot be before the issue date'
    : null;
};

const isCustomRate = (item: LineItemValues) => item.taxRate === 'custom';

const itemRule =
  (
    rule: (value: number | string) => string | null,
    condition?: (item: LineItemValues) => boolean
  ) =>
  (value: number | string, values: InvoiceValues, path: string) => {
    const item = values.items[Number(path.split('.')[1])];
    return !condition || (item && condition(item)) ? rule(value) : null;
  };

// Keys follow the order of the fields on the page: the first error is the first invalid field
export const invoiceRules: FormRulesRecord<InvoiceValues> = {
  clientId: isNotEmpty('Select a client'),
  invoiceNumber: (value) => (value.trim() ? null : 'Enter an invoice number'),
  issueDate: isNotEmpty('Enter an issue date'),
  dueDate: dueDateRule,
  items: {
    [formRootRule]: (items) =>
      items.length < MIN_ITEMS || items.length > MAX_ITEMS
        ? `Add between ${MIN_ITEMS} and ${MAX_ITEMS} items`
        : null,
    description: (value) => (value.trim() ? null : 'Enter a description'),
    quantity: itemRule(quantityRule),
    unitPrice: itemRule(unitPriceRule),
    customTaxRate: itemRule(customTaxRateRule, isCustomRate),
  },
  discountValue: when((values) => values.discountEnabled, discountRule),
  customTermDays: when((values) => values.paymentTerms === 'custom', customTermDaysRule),
  paymentMethods: (value) => (value.length > 0 ? null : 'Select at least one payment method'),
  notes: (value) =>
    value.length > NOTES_MAX_LENGTH ? `Notes must be ${NOTES_MAX_LENGTH} characters or less` : null,
};

export const DRAFT_FIELDS = ['clientId', 'invoiceNumber'] as const;
